  root.addEventListener('input',e=>{if(!e.target.matches('.a83-code'))return;state.a83Draft=e.target.value;phone.querySelector('.a83-dirty').hidden=state.a83Draft===state.a83Saved;phone.querySelector('[data-action=a83-save]').disabled=state.a83Draft===state.a83Saved;phone.querySelector('.a83-warning-slot').innerHTML=a83Warning();});
